head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.gIsurCd;
scwin.gSeq;
scwin.gComNm;
scwin.contnId;
scwin.gDate;
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market;
scwin.vScrenID = 'ULDSTF39300.xml';
scwin.ToDay = new Date();
scwin.yyyyList = parseInt(scwin.ToDay.getYear(), 10) + 8;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    var str = "";
    for (var i = scwin.yyyyList; i >= 2018; i--) {
        str += i + "^" + i + ",";
    }
    str = str.substring(0, str.length - 1);
    cmb_strt_YYYY.CBData = str;
    cmb_end_YYYY.CBData = str;
    $c.stf.setObjectValue(cmb_strt_YYYY, "2018");
};
scwin.fn_CheckCond = function() {
    scwin.fn_SetItemGridHeaderCheck();
    scwin.fn_Search();
};


//dataid 생성
scwin.fn_SetItemGridHeaderCheck = function() {
    var headerString = "";
    headerString += "SPECL_COM_SEQ:STRING(6),ISUR_CD:STRING(5),COM_ABBRV:STRING(255),APFM_SUBMIT_DD:STRING(8),SPECL_STRT_DD:STRING(8),SKIL_VALU_GRD_NM:STRING(100),SKIL_VALU_ACQST_DD:STRING(8),VALU_INST_NM:STRING(100),SPECL_COM_ADM_REMK:STRING(2000),LST_CHG_DDTM:STRING(14),LST_CHG_EMP_NO:STRING(6),";
    for (var i = scwin.yyyyList; i >= 2018; i--) {
        if (i == '2018') {
            headerString += "YYYY_" + i + ":STRING(1)";
        } else {
            headerString += "YYYY_" + i + ":STRING(1),";
        }
    }
    //alert(headerString);


    //dts_List.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
    dts_List.insertRow();
};


// 고정된 그리드 생성
scwin.fn_SetBasicHeader = function(grdObj) {
    grdObj.ToolTip = "use=true;header=true;alt=true;createtime=1000;destroytime=30000;fontsize=9;color=#0f0f0f;backcolor=white;edgecolor=green;";
    grdObj.FillArea = "true";
    grdObj.AutoResizingWithHeader = "true";
    var basic = "";
    basic += "<fC>color='#343434' headalign='center' sumbgcolor='#fefaef' headvalign='center' sumcolor='#343434' ";
    basic += "headbgcolor='#598fd5' headcolor='#ffffff' ";
    basic += "name='번호' id='NO' align='center' width='30' show='true' value='{currow}' </fC>\n";
    basic += "<fC>color='#343434' headalign='center' sumbgcolor='#fefaef' headvalign='center' sumcolor='#343434' ";
    basic += "headbgcolor='#598fd5' headcolor='#ffffff' ";
    basic += "name='회사코드' id='ISUR_CD' align='center' width='75'  show='true' sort='True'  </fC>\n";
    basic += "<fC>color='#343434' headalign='center' sumbgcolor='#fefaef' headvalign='center' sumcolor='#343434' ";
    basic += "headbgcolor='#598fd5' headcolor='#ffffff' ";
    basic += "name='시퀀스' id='SPECL_COM_SEQ' align='center' width='80'  show='false' </fC>\n";
    basic += "<fC>color='#343434' headalign='center' sumbgcolor='#fefaef' headvalign='center' sumcolor='#343434' ";
    basic += "headbgcolor='#598fd5' headcolor='#ffffff' ";
    basic += "bgcolor='#FFFF99' ";
    basic += "name='회사명' id='COM_ABBRV' align='left' width='170' cursor='hand' show='true' sort='True'  </fC>\n";
    basic += "<fC>color='#343434' headalign='center' sumbgcolor='#fefaef' headvalign='center' sumcolor='#343434' ";
    basic += "headbgcolor='#598fd5' headcolor='#ffffff' ";
    basic += "name='신청서제출일' id='APFM_SUBMIT_DD' show='true' mask='XXXX-XX-XX' align='center' width='100' sort='True' </fC>\n";
    basic += "<fC>color='#343434' headalign='center' sumbgcolor='#fefaef' headvalign='center' sumcolor='#343434' ";
    basic += "headbgcolor='#598fd5' headcolor='#ffffff' ";
    basic += "name='특례적용일' id='SPECL_STRT_DD' show='true' mask='XXXX-XX-XX' align='center' width='90' sort='True' </fC>\n";

    /*	basic += "<C>color='#343434' headalign='center' sumbgcolor='#fefaef' headvalign='center' sumcolor='#343434' ";
		basic += "headbgcolor='#598fd5' headcolor='#ffffff' ";
		basic += "name='기술평가등급' id='SKIL_VALU_GRD_NM' align='center' width='100'  show='true' sort='True'  </C>\n";

		basic += "<C>color='#343434' headalign='center' sumbgcolor='#fefaef' headvalign='center' sumcolor='#343434' ";
		basic += "headbgcolor='#598fd5' headcolor='#ffffff' ";
		basic += "name='기술성평가획득일' id='SKIL_VALU_ACQST_DD' show='true' mask='XXXX-XX-XX' align='center' width='120' sort='True' </C>\n";

		basic += "<C>color='#343434' headalign='center' sumbgcolor='#fefaef' headvalign='center' sumcolor='#343434' ";
		basic += "headbgcolor='#598fd5' headcolor='#ffffff' ";
		basic += "name='전문평가기관명' id='VALU_INST_NM' align='center' width='120'  show='true' sort='True'  </C>\n";
*/
    grdObj.Format = basic;
};


// 동적 그리드 생성(년도)
scwin.fn_SetMultiHeader = function(grdObj) {
    // 기본헤더
    scwin.fn_SetBasicHeader(grdObj);

    // Grid Style
    var GRID_STYLE_CTAG = " width=80 align='center' headbgcolor=\"#598fd5\" headcolor=\"#ffffff\" color=\"#343434\" sort='True' ";

    // grid format 계층태그상수
    var LEVEL_ONE_BEGIN_TAG = "<C>";
    var LEVEL_ONE_END_TAG = "</C>\n";

    // 그리드포멧결과
    var gridFormat = "";
    var gSTRT_YYYY = $c.stf.getObjectValue(cmb_strt_YYYY);
    var gEND_YYYY = $c.stf.getObjectValue(cmb_end_YYYY);
    for (var i = gSTRT_YYYY; i <= gEND_YYYY; i++) {
        gridFormat += LEVEL_ONE_BEGIN_TAG;
        gridFormat += "id=\"YYYY_" + i + "\"" + " name=\"" + i + "년\"" + GRID_STYLE_CTAG;
        gridFormat += LEVEL_ONE_END_TAG;
    }
    grdObj.Format += gridFormat;
    scwin.fn_SetEndHeader(grdObj);
};



// 고정된 그리드 생성
scwin.fn_SetEndHeader = function(grdObj) {
    var basic = "";
    basic += "<C>color='#343434' headalign='center' sumbgcolor='#fefaef' headvalign='center' sumcolor='#343434' ";
    basic += "headbgcolor='#598fd5' headcolor='#ffffff' ";
    basic += "name='기술평가등급' id='SKIL_VALU_GRD_NM' align='center' width='100'  show='true' sort='True'  </C>\n";
    basic += "<C>color='#343434' headalign='center' sumbgcolor='#fefaef' headvalign='center' sumcolor='#343434' ";
    basic += "headbgcolor='#598fd5' headcolor='#ffffff' ";
    basic += "name='기술성평가획득일' id='SKIL_VALU_ACQST_DD' show='true' mask='XXXX-XX-XX' align='center' width='120' sort='True' </C>\n";
    basic += "<C>color='#343434' headalign='center' sumbgcolor='#fefaef' headvalign='center' sumcolor='#343434' ";
    basic += "headbgcolor='#598fd5' headcolor='#ffffff' ";
    basic += "name='전문평가기관명' id='VALU_INST_NM' align='center' width='120'  show='true' sort='True'  </C>\n";
    grdObj.Format += basic;
};
scwin.fn_Search = function() {
    scwin.fn_SetMultiHeader(grd_Grid);
    var url_list = "/ExceptionRuleAdm.do?method=listExceptionRuleAdm";
    var url_cond = "&ISUR_CD=" + $c.stf.getObjectValue(txb_isur_cd) + "&STRT_YYYY=" + $c.stf.getObjectValue(cmb_strt_YYYY) + "&END_YYYY=" + $c.stf.getObjectValue(cmb_end_YYYY) + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    // 그리드의 데이타 조회
    dts_List.DataID = encodeURI(url_list + url_cond);
    dts_List.reset();
    $c.cm.ShowWin(grd_Grid);
};




// 그리드에서 클릭 row의 변수셋팅
scwin.fn_setContnId = function(obj) {
    scwin.gIsurCd = dts_List.getCellData(eval(obj), "ISUR_CD");
    scwin.gComNm = dts_List.getCellData(eval(obj), "COM_ABBRV");
    scwin.gSeq = dts_List.getCellData(eval(obj), "SPECL_COM_SEQ");
};
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    // 클릭된 값 변수에 셋팅
    scwin.fn_setContnId(row);
    if (colid == "COM_ABBRV") {
        $c.stf.fn_PopupCorpInfo();
    }
    //특례적용일 또는 년도 있는 부분 선택시 수정화면으로 이동
    else {
        scwin.contnId = "U";
        var url = "/dsclmgt/ULDSTF39302.gfm";
        var winTitle = "제약바이오특례기업 관리 상세화면";
        await $c.frame.CreateDialogFrame("ULDSTF39302", url, winTitle, 200, 100, 735, 630, "window");
        scwin.contnId = "";
    }
};
scwin.btn_Search_onclick = function() {
    scwin.fn_CheckCond();
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    $c.data.downloadGridViewExcel(grd_Grid, "제약바이오특례기업관리", "", "8");
};
scwin.btn_Input_onclick = async function() {
    scwin.contnId = "I";
    await $c.frame.CreateDialogFrame("gform", "/dsclmgt/ULDSTF39302.gfm", "제약바이오특례기업 등록", 200, 100, 735, 630, "window");
    scwin.contnId = "";
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    if (dts_List.errorMsg) {
        $c.win.alert(dts_List.errorMsg);
    } else {
        $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    }
    $c.cm.CloseWin(rowcount, grd_Grid);
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
    $c.cm.CloseWin('', grd_Grid);
};
scwin.img_com_srch_onclick = function() {
    $c.cm.IsurcdSearch(txb_isur_cd, txb_com_abbrv);
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.txb_isur_cd_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_isur_cd.getValue() == "") {
        txb_com_abbrv.setValue("");
    }
};
scwin.txb_isur_cd_onfocus = function() {
    Grd_com_isur.style.top = "31px";
    Grd_com_isur.style.left = "78px";
    Grd_com_isur.style.display = "none";
};
scwin.txb_isur_cd_onkeyup = function() {
    if (txb_isur_cd.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else {
        return true;
    }
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.gform_onload = function() {
    // 패널라운드 처리
    $c.cm.PanelToGroupBox(panel_1);
    scwin.fn_SetCode();
    $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
    scwin.fn_CheckCond();
};
